def search(arr):
    if not arr:
        return None

    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        # Check if the middle element is part of a pair to its left
        if arr[mid] == arr[mid - 1]:
            # The single element must be to the right of this pair
            left = mid + 1
        elif arr[mid] == arr[mid + 1]:
            # The single element must be to the left of this pair
            right = mid - 1
        else:
            # Found the unique element
            return arr[mid]

    return arr[left]

